def format_cents(cents):
    dollars = cents // 100
    remaining_cents = cents % 100
    return f"${dollars}.{remaining_cents:02d}"

if __name__ == "__main__":
    import sys
    if len(sys.argv) > 1:
        try:
            amount = int(sys.argv[1])
            print(format_cents(amount))
        except ValueError:
            pass

